CREATE PROCEDURE dbo.OrdersByStatus
  @status VARCHAR(20) = 'open',
  @count INT OUTPUT
AS
BEGIN
  SET NOCOUNT ON;
  SELECT id, total FROM orders WHERE status = @status;
  SET @count = @@ROWCOUNT;
END;

