-- Safe inventory decrement under concurrency
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRAN;
  SELECT qty FROM inventory WHERE sku=@s;   -- range lock held
  UPDATE inventory SET qty = qty - @n WHERE sku=@s AND qty >= @n;
COMMIT;

-- Retry template for deadlock victims (error 1205)
DECLARE @tries INT = 0;
WHILE @tries < 3 BEGIN
  BEGIN TRY BEGIN TRAN; /* ...work... */ COMMIT; BREAK; END TRY
  BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK;
    IF ERROR_NUMBER() <> 1205 THROW; SET @tries += 1; END CATCH
END;

